    func get(_ key: String) -> String?
}
final class FakeCache: KeyValueCache {
    private var dict: [String: String] = [:]
    func set(_ key: String, _ value: String) { dict[key] = value }
    func get(_ key: String) -> String? { dict[key] }
}
