protocol TimeProvider { func currentYear() -> Int }
struct FixedYearProvider: TimeProvider { func currentYear() -> Int { 2026 } }
final class TimeDependentService {
    let provider: TimeProvider
    init(provider: TimeProvider = FixedYearProvider()) { self.provider = provider }
    func currentYearText() -> String { "Year: \(provider.currentYear())" }
}
let s = TimeDependentService(provider: FixedYearProvider())
print(s.currentYearText())

enum ServiceError: Error { case connectionFailed }
protocol DataFetcher { func fetchData() throws -> String }
struct FailingStub: DataFetcher {
    func fetchData() throws -> String { throw ServiceError.connectionFailed }
}
final class DataPresenter {
    let fetcher: DataFetcher
    init(fetcher: DataFetcher) { self.fetcher = fetcher }
    func render() -> String {
        do { return try fetcher.fetchData() }
        catch { return "Handled error" }
    }
}
let p = DataPresenter(fetcher: FailingStub())
print(p.render())

